  "faq": {
    "kicker": "Imibuzo eminingi",
    "title": "Imibuzo ngaphambi kokubuza.",
    "subtitle": "Konke okufuneka abantu basekhaya nabamqambi bafuna. Usengakwazi ukuthola ukuthi kuqhubeka kanjani?",
    "call": "Biza",
    "items": {
      "f1": {
        "q": "Ninasebenza nabantu basekhaya, noma kuphela nabamqambi abaningi?",
        "a": "Konke. Thina sisebenza ngezinhlangozo zokugcina zeClear Vu, izinhlangozi, kanye nezinsebenzo ezincane zabantu basekhaya eGauteng, futhi sinamandla okuphucula umsebenzi, izinhlelo zokuvikela, nokwakha okufuneka abamqambi nabasebenzi basekuhlonisheni bafune emicimini eminingi."
      },
      "f2": {
        "q": "Izindawni ezini uthola ukusebenza kuzo?",
        "a": "Sise eChloorkop, eKempton Park futhi sithuthela ngokuphelele eGreater Johannesburg — Sandton, Midrand, Soweto, Roodepoort, Randburg, i-East Rand (Germiston, Boksburg, Benoni) kanye ne-Centurion/Pretoria ngokushintshana."
      },
      "f3": {
        "q": "Ngaba ngiyakufaka kanani ekhawulini ekhethiwe?",
        "a": "Dlisa usizo ofuna, indawo yesayithi, uhlobo lwesebenzo olungekho, kanye nokunye okungakwazi ukuthinta isikhathi noma ubude obungakwazi ukuvumela ukufikelela. Izithombe zesayithi noma izinhlangozo ezingaphakathi ziyathutha ukukhawula ngokushesha."
      },
      "f4": {
        "q": "Ungakwazi ukuthola isiphetho ngemva kokubiza kanani?",
        "a": "Sithanda ukukhawula izicelo zokukhawula ngokushesha futhi sithi isiphetho uma sithole ukwazi okudingekayo ukukhuthaza umsebenzi wakhe — ngokuvamile ngosuku olusemthethweni lokubiza kanye ne-WatsApp."
      },
      "f5": {
        "q": "Uyakubiza ngaphambi kokuthi umkhawulo wakho uyatholakala?",
        "a": "Yebo. Uma sithanda ukwazi okunye, singabiza kuqala ukuqinisekisa imingcele, izidingo zomsebenzi, noma izimo zesayithi. Ukugcina kwezinhlangozo kanye nezinhlangozi, thanda ukukala ngasesayithi ukuze ukhawulo kube ngumkhawulo oqinisekile."
      },
      "f6": {
        "q": "Ukukhetha kwakhu kungasebenzi kanye kuyaqinisekiswa?",
        "a": "Yebo. Izinhlangozo zokukhetha zisetshenziswa ngokulingana nezingxenye zokuqhuba zikaSANS, zithathelwa ngamakhadi, kanye ziqinisekiswa ngokujikijela isikhathi esedlulelile. Ukususwa kwenziwa ngumsebenzi oqashwe ngokufunda."
      },
      "f7": {
        "q": "Ukuthi ukuthi CIDB 6 kusho kanjani ngokwami?",
        "a": "Umlando weConstruction Industry Development Board uyabelana abasebenzi ngokwakha. Ukuhlonishwa kukaCIDB 6 kusho ukuthi Entlelo kuyabelwe ngokushesha ukukhetha kanye nokuthuthela imisebenzo eminingi yezinhlangano zezisekelo kanye nezingqongqoshe — amandla namandla okulingana ofuna ngokwakho umsebenzi, omkhulu noma omncane."
      },
      "f8": {
        "q": "Ninasebenza nge welding noma ngokungeyona?",
        "a": "Yebo — ukufinyeza kwezinkuni kanye nokufinyezwa kwezinkuni kuyisebenzi esisekhulini. Izinhlangozi, izinhlaka, amagoda kanye nezinkuni ezisekwe zikhiqizwa ngabafundi besithathu besithathu besethu, okuvumela ukulingana kwekucucuka nokugcina amasethi angaphakathi."
      }
    }
  },
